package org.stellarproximology.trident;
import android.app.*;import android.content.*;import android.os.*;
public final class BridgeForegroundService extends Service{private LocalBridgeServer server;public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("trident_hands","Trident hands",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);}Intent i=new Intent(this,MainActivity.class);PendingIntent p=PendingIntent.getActivity(this,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"trident_hands"):new Notification.Builder(this);startForeground(58,b.setContentTitle("Trident hands ready").setContentText("Local bridge · 127.0.0.1:8787").setSmallIcon(R.drawable.trident_planet).setContentIntent(p).setOngoing(true).build());server=new LocalBridgeServer(this,8787);server.start();}public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public void onDestroy(){if(server!=null)server.stop();super.onDestroy();}public IBinder onBind(Intent i){return null;}}
